mapper.select:
SELECT id, title, content, type, CASE type WHEN 1 THEN '预约通知' WHEN 2 THEN '支付通知' WHEN 3 THEN '退款通知' WHEN 4 THEN '公告通知' WHEN 5 THEN '系统通知' WHEN 6 THEN 'Agent通知' WHEN 7 THEN '商城通知' ELSE '未知通知' END AS typeName, business_id AS businessId, business_no AS businessNo, business_type AS businessType, read_status AS readStatus, create_time AS createTime, read_time AS readTime FROM notification WHERE user_id = #{userId} AND is_deleted = 0
AND read_status = #{readStatus}
ORDER BY create_time DESC

mapper.update:
UPDATE notification
SET read_status = 1,
    read_time = #{readTime},
    update_time = #{readTime}
WHERE id = #{id}
  AND user_id = #{userId}
  AND is_deleted = 0

UPDATE notification
SET deleted = 1,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND is_deleted = 0
